tinymce.PluginManager.add('dbrepo', function (editor, url) {

  RS.i18n = RS.i18n || {};
  RS.i18n["legacyjs.core.dbrepo.insertLink"] = RS.i18n["legacyjs.core.dbrepo.insertLink"] || "Insert link";
  RS.i18n["legacyjs.core.dbrepo.insertRows"] = RS.i18n["legacyjs.core.dbrepo.insertRows"] || "Insert rows";
  RS.i18n["legacyjs.core.dbrepo.insertRowsHint"] = RS.i18n["legacyjs.core.dbrepo.insertRowsHint"] || "Insert rows needs a table or view. Expand a database to choose one.";
  const closeButtonLabel = RS.msg("legacyjs.common.close");
  const insertRowsButtonLabel = RS.msg("legacyjs.core.dbrepo.insertRows");
  const insertLinkButtonLabel = RS.msg("legacyjs.core.dbrepo.insertLink");
  const dialogUrl = RS.withCacheVersion(url + "/dialog.html");

  const findDBRepoDialogFooter = () => {
    const $dialogIframe = $(".tox-dialog iframe").filter(function () {
      return this.src && this.src.includes("/dbrepo/dialog.html");
    }).last();
    return $dialogIframe.closest(".tox-dialog").find(".tox-dialog__footer");
  };

  const findFooterButton = ($footer, label) => $footer.find("button").filter(function () {
    return $(this).text().trim() === label;
  }).first();

  editor.addCommand("cmdDBRepo", function () {
    editor.windowManager.openUrl({
      title: "DBRepo",
      url: dialogUrl,
      width: 1200,
      height: 1000,
      buttons: [
        { type: "cancel", id: "close", name: "close", text: closeButtonLabel },
        { type: "custom", id: "insertRows", name: "insertRows", text: insertRowsButtonLabel, disabled: true },
        { type: "custom", id: "insert", name: "insert", text: insertLinkButtonLabel, primary: true, disabled: true }
      ],
      onAction(dialogApi, button) {
        if (button.name === "insert") {
          editor.fire("dbrepo-insert");
        } else if (button.name === "insertRows") {
          editor.fire("dbrepo-insert-rows");
        }
      },
      onMessage(dialogApi, details) {
        const $footer = findDBRepoDialogFooter();
        const $closeButton = findFooterButton($footer, closeButtonLabel);
        const $insertRowsButton = findFooterButton($footer, insertRowsButtonLabel);
        const $insertButton = findFooterButton($footer, insertLinkButtonLabel);
        const $buttons = $closeButton.add($insertRowsButton).add($insertButton);
        let $insertRowsHint = $footer.find(".dbrepo-insert-rows-hint");
        if (!$insertRowsHint.length && $buttons.length === 3) {
          $insertRowsHint = $("<div class=\"dbrepo-insert-rows-hint\"></div>");
          const $buttonRow = $("<div class=\"dbrepo-dialog-button-row\"></div>");
          $footer.css({
            "flex-wrap": "wrap"
          });
          $insertRowsHint.css({
            "color": "#626262",
            "flex": "0 0 100%",
            "font-size": "12px",
            "margin-bottom": "6px",
            "text-align": "right",
            "width": "100%",
            "white-space": "normal"
          });
          $buttonRow.css({
            "display": "flex",
            "flex": "0 0 100%",
            "gap": "8px",
            "justify-content": "flex-end",
            "width": "100%"
          });
          $footer.prepend($insertRowsHint);
          $buttons.appendTo($buttonRow);
          $footer.append($buttonRow);
        }

        if (details.mceAction === "enable") {
          $insertButton.prop("disabled", null);
          $insertButton.removeAttr("disabled");
        } else if (details.mceAction === "disable") {
          $insertButton.attr("disabled", "disabled");
        }
        if (details.rowsAction === "enable") {
          $insertRowsButton.prop("disabled", null);
          $insertRowsButton.removeAttr("disabled");
          $insertRowsHint.text("").hide();
        } else if (details.rowsAction === "disable") {
          $insertRowsButton.attr("disabled", "disabled");
          $insertRowsHint.text(RS.msg("legacyjs.core.dbrepo.insertRowsHint")).show();
        }
      }
    });
  });

  editor.ui.registry.addButton('dbrepo', {
    icon: 'dbrepo',
    tooltip: 'DBRepo',
    onAction: function () {
      editor.execCommand("cmdDBRepo");
    }
  });

  editor.ui.registry.addMenuItem('optDBRepo', {
    text: 'DBRepo',
    icon: 'dbrepo',
    onAction: function () { editor.execCommand("cmdDBRepo"); },
  });

  if (!window.insertActions) window.insertActions = new Map();
  window.insertActions.set("optDBRepo", {
    text: 'DBRepo',
    icon: 'dbrepo',
    action: () => {
      editor.execCommand("cmdDBRepo");
    },
  });
});
